    final Stack<AbstractType> stack = getOutputFrame().getStack();
    final List<AbstractType> outputTypes = new ArrayList<>();

    for (int i = 0; i < descriptor.length(); i++) {
        final char c = descriptor.charAt(i);
        if (c == 'Z') {
            outputTypes.add(AbstractType.BOOLEAN);
        } else if (c == 'B') {
            outputTypes.add(AbstractType.BYTE);
        } else if (c == 'C') {
            outputTypes.add(AbstractType.CHARACTER);
        } else if (c == 'S') {
            outputTypes.add(AbstractType.SHORT);
        } else if (c == 'I') {
            outputTypes.add(AbstractType.INTEGER);
        } else if (c == 'F') {
            outputTypes.add(AbstractType.FLOAT);
        } else if (c == 'J') {
            outputTypes.add(AbstractType.LONG);
